import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { roomAPI, bookingAPI } from '../services/api';
import { useAuth } from '../context/AuthContext';
import LocationPicker from '../components/LocationPicker';

const OwnerDashboard = () => {
  const { user } = useAuth();
  const [rooms, setRooms] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [roomBookings, setRoomBookings] = useState({}); // NOUVEAU: réservations groupées par salle
  const [expandedRooms, setExpandedRooms] = useState([]); // NOUVEAU: salles dépliées
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState({
    rooms: true,
    bookings: true,
    stats: true
  });
  
  const [newRoom, setNewRoom] = useState({
    title: '',
    description: '',
    capacity: '',
    price_per_hour: '',
    address: '',
    city: '',
    postal_code: '',
    country: 'France'
  });
  const [imageFile, setImageFile] = useState(null);
  const [showRoomForm, setShowRoomForm] = useState(false);

  useEffect(() => {
    if (user) {
      fetchOwnerData();
    }
  }, [user]);

  const fetchOwnerData = async () => {
    await Promise.all([
      fetchOwnerRooms(),
      fetchOwnerBookings(),
      fetchOwnerStats()
    ]);
  };

  const fetchOwnerRooms = async () => {
    try {
      const response = await roomAPI.getOwnerRooms();
      setRooms(response.data.rooms || []);
    } catch (error) {
      console.error('Erreur chargement salles:', error);
    } finally {
      setLoading(prev => ({ ...prev, rooms: false }));
    }
  };

  const fetchOwnerBookings = async () => {
    try {
      const response = await bookingAPI.getOwnerBookings();
      const bookingsData = response.data.bookings || [];
      setBookings(bookingsData);
      
      // Grouper les réservations par salle
      const grouped = {};
      bookingsData.forEach(booking => {
        if (!grouped[booking.room_id]) {
          grouped[booking.room_id] = [];
        }
        grouped[booking.room_id].push(booking);
      });
      setRoomBookings(grouped);
      
    } catch (error) {
      console.error('Erreur chargement réservations:', error);
    } finally {
      setLoading(prev => ({ ...prev, bookings: false }));
    }
  };

  const fetchOwnerStats = async () => {
    try {
      const response = await roomAPI.getOwnerStats();
      setStats(response.data.stats);
    } catch (error) {
      console.error('Erreur chargement stats:', error);
    } finally {
      setLoading(prev => ({ ...prev, stats: false }));
    }
  };

  // NOUVEAU: Basculer l'affichage des réservations d'une salle
  const toggleRoomBookings = (roomId) => {
    if (expandedRooms.includes(roomId)) {
      setExpandedRooms(expandedRooms.filter(id => id !== roomId));
    } else {
      setExpandedRooms([...expandedRooms, roomId]);
    }
  };

  // NOUVEAU: Obtenir les réservations d'une salle spécifique
  const getRoomBookings = (roomId) => {
    return roomBookings[roomId] || [];
  };

  // NOUVEAU: Compter les réservations par statut pour une salle
  const getBookingStats = (roomId) => {
    const roomBookingsList = getRoomBookings(roomId);
    return {
      total: roomBookingsList.length,
      pending: roomBookingsList.filter(b => b.status === 'pending').length,
      confirmed: roomBookingsList.filter(b => b.status === 'confirmed').length,
      completed: roomBookingsList.filter(b => b.status === 'completed').length,
      cancelled: roomBookingsList.filter(b => b.status === 'cancelled').length
    };
  };

  const handleNewRoomChange = (e) => {
    setNewRoom({
      ...newRoom,
      [e.target.name]: e.target.value
    });
  };

  const handleImageChange = (e) => {
    if (e.target.files && e.target.files[0]) {
      setImageFile(e.target.files[0]);
    }
  };

  const handleAddRoom = async (e) => {
    e.preventDefault();
    
    const formData = new FormData();
    
    Object.keys(newRoom).forEach(key => {
      formData.append(key, newRoom[key]);
    });
    
    if (imageFile) {
      formData.append('image', imageFile);
    }
    
    try {
      const response = await fetch('http://localhost:5000/api/rooms', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: formData
      });
      
      const data = await response.json();
      
      if (data.success) {
        setRooms([...rooms, data.data.room]);
        setNewRoom({
          title: '',
          description: '',
          capacity: '',
          price_per_hour: '',
          address: '',
          city: '',
          postal_code: '',
          country: 'France'
        });
        setImageFile(null);
        setShowRoomForm(false);
        fetchOwnerStats();
      } else {
        console.error('Erreur création salle:', data.message);
        alert(data.message || 'Erreur lors de la création de la salle');
      }
    } catch (error) {
      console.error('Erreur création salle:', error);
      alert('Erreur lors de la création de la salle');
    }
  };

  const handleConfirmBooking = async (bookingId) => {
    try {
      const response = await bookingAPI.confirm(bookingId);
      if (response.success) {
        fetchOwnerBookings(); // Recharger les réservations
      }
    } catch (error) {
      console.error('Erreur confirmation:', error);
    }
  };

  const handleCancelBooking = async (bookingId) => {
    if (!window.confirm('Annuler cette réservation ?')) return;
    
    try {
      // Note: On utilise cancel au lieu de delete
      const response = await bookingAPI.cancel(bookingId);
      if (response.success) {
        fetchOwnerBookings(); // Recharger les réservations
      }
    } catch (error) {
      console.error('Erreur annulation:', error);
    }
  };

  const handleDeleteRoom = async (roomId) => {
    if (!window.confirm('Supprimer cette salle ?')) return;
    
    try {
      const response = await roomAPI.delete(roomId);
      if (response.success) {
        setRooms(rooms.filter(r => r.id !== roomId));
        fetchOwnerStats();
      }
    } catch (error) {
      console.error('Erreur suppression:', error);
    }
  };

  return (
    <div className="main-content">
      <div className="card">
        <h1>Espace Propriétaire</h1>
        <p>Bienvenue dans votre espace de gestion, <strong>{user?.first_name}</strong></p>
      </div>

     {/* Statistiques */}
      <div className="card">
        <h2>📊 Statistiques</h2>
        {loading.stats ? (
          <p>Chargement des statistiques...</p>
        ) : stats ? (
          <div className="stats-grid" style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
            gap: '20px',
            marginTop: '20px'
          }}>
            <div className="stat-card" style={{
              background: 'linear-gradient(135deg, #53cca68d 0%)',
              color: 'white',
              padding: '25px',
              borderRadius: '12px',
              textAlign: 'center',
              boxShadow: '0 4px 15px rgba(254, 252, 252, 0.1)'
            }}>
              <h3 style={{ fontSize: '2.5rem', margin: '0 0 10px 0' }}>{stats.total_rooms || 0}</h3>
              <p style={{ margin: 0, fontSize: '1.1rem' }}>Salles totales</p>
            </div>
            <div className="stat-card" style={{
              background: 'linear-gradient(135deg, #53cca68d 0%)',
              color: 'white',
              padding: '25px',
              borderRadius: '12px',
              textAlign: 'center',
              boxShadow: '0 4px 15px rgba(0,0,0,0.1)'
            }}>
              <h3 style={{ fontSize: '2.5rem', margin: '0 0 10px 0' }}>{stats.available_rooms || 0}</h3>
              <p style={{ margin: 0, fontSize: '1.1rem' }}>Salles disponibles</p>
            </div>

            <div className="stat-card" style={{
                 background: 'linear-gradient(135deg, #53cca68d 0%)',
                 color: 'white',
                 padding: '25px',
                 borderRadius: '12px',
                 textAlign: 'center',
                 boxShadow: '0 4px 15px rgba(0,0,0,0.1)'
                 }}>
                <h3 style={{ fontSize: '2.5rem', margin: '0 0 10px 0' }}>{bookings.length}</h3>
                <p style={{ margin: 0, fontSize: '1.1rem' }}>Réservations</p>
            </div>
            
          </div>
        ) : (
          <p>Aucune statistique disponible</p>
        )}
      </div>








      {/* Gestion des salles AVEC RÉSERVATIONS */}
      <div className="card"style={{
        marginTop: '2rem',
        padding: '2rem',
        borderRadius: '15px',
        boxShadow: '0 5px 20px rgba(0, 0, 0, 0.1)',
        background: 'white'
      }}>
        <div className="section-header">
          <h2>🏢 Mes salles ({rooms.length})</h2>
          <button 
            onClick={() => setShowRoomForm(!showRoomForm)}
            className="btn btn-primary"
          >
            {showRoomForm ? 'Annuler' : '+ Ajouter une salle'}
          </button>
        </div>

        {showRoomForm && (
          <form onSubmit={handleAddRoom} className="room-form" encType="multipart/form-data">
            <h3>Nouvelle salle</h3>
            
            <div className="form-group">
              <label>Image de la salle (optionnel)</label>
              <input
                type="file"
                name="image"
                accept="image/*"
                onChange={handleImageChange}
                className="form-input"
              />
              {imageFile && (
                <p style={{ marginTop: '5px', color: 'green' }}>
                  ✅ Image sélectionnée: {imageFile.name}
                </p>
              )}
              <small style={{ color: '#666' }}>
                Formats acceptés: JPG, PNG, GIF, WebP (max 5MB)
              </small>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label>Titre *</label>
                <input
                  type="text"
                  name="title"
                  value={newRoom.title}
                  onChange={handleNewRoomChange}
                  required
                  className="form-input"
                />
              </div>
              <div className="form-group">
                <label>Ville *</label>
                <input
                  type="text"
                  name="city"
                  value={newRoom.city}
                  onChange={handleNewRoomChange}
                  required
                  className="form-input"
                />
              </div>
            </div>

            {newRoom.city && (
              <div className="form-group">
                <LocationPicker
                  city={newRoom.city}
                  onLocationSelected={(lat, lng) => {
                    setNewRoom({
                      ...newRoom,
                      latitude: lat,
                      longitude: lng
                    });
                  }}
                />
              </div>
            )}

            <div className="form-row">
              <div className="form-group">
                <label>Capacité *</label>
                <input
                  type="number"
                  name="capacity"
                  value={newRoom.capacity}
                  onChange={handleNewRoomChange}
                  required
                  className="form-input"
                  min="1"
                />
              </div>
              <div className="form-group">
                <label>Prix/heure (DA) *</label>
                <input
                  type="number"
                  name="price_per_hour"
                  value={newRoom.price_per_hour}
                  onChange={handleNewRoomChange}
                  required
                  className="form-input"
                  min="0"
                  step="0.01"
                />
              </div>
            </div>

            <div className="form-group">
              <label>Adresse *</label>
              <input
                type="text"
                name="address"
                value={newRoom.address}
                onChange={handleNewRoomChange}
                required
                className="form-input"
              />
            </div>

            <div className="form-group">
              <label>Description</label>
              <textarea
                name="description"
                value={newRoom.description}
                onChange={handleNewRoomChange}
                className="form-input"
                rows="3"
              />
            </div>
            
            <input
              type="hidden"
              name="latitude"
              value={newRoom.latitude || ''}
            />
            <input
              type="hidden"
              name="longitude"
              value={newRoom.longitude || ''}
            />

            <button type="submit" className="btn btn-primary">
              Créer la salle
            </button>
          </form>
        )}







        {loading.rooms ? (
          <p>Chargement des salles...</p>
        ) : rooms.length > 0 ? (
          <div className="rooms-list">
            {rooms.map(room => {
              const roomBookingStats = getBookingStats(room.id);
              const isExpanded = expandedRooms.includes(room.id);
              
              return (
                <div key={room.id} className="room-item">
                  <div className="room-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div className="room-info">
                      <h4>{room.title}</h4>
                      <p>{room.city} • {room.capacity} pers. • {room.price_per_hour}DA/h</p>
                      <p className="room-status">
                        {room.is_available ? '✅ Disponible' : '❌ Indisponible'}
                      </p>
                      
                      {/* Statistiques rapides des réservations */}
                      {roomBookingStats.total > 0 && (
                        <div className="booking-stats" style={{ 
                          marginTop: '0.5rem', 
                          fontSize: '0.9rem',
                          color: '#666'
                        }}>
                          <span>📅 {roomBookingStats.total} réservation(s) - </span>
                          {roomBookingStats.pending > 0 && <span className="pending-badge">⏳ {roomBookingStats.pending} en attente</span>}
                          {roomBookingStats.confirmed > 0 && <span className="confirmed-badge">✅ {roomBookingStats.confirmed} confirmée(s)</span>}
                        </div>
                      )}
                    </div>
                    
                    <div className="room-actions">
                      <Link to={`/rooms/${room.id}`} className="btn btn-secondary btn-sm">
                        Voir
                      </Link>
                      
                      {/* Bouton pour afficher/masquer les réservations */}
                      {roomBookingStats.total > 0 && (
                        <button 
                          onClick={() => toggleRoomBookings(room.id)}
                          className="btn btn-primary btn-sm"
                          style={{ marginLeft: '0.5rem' }}
                        >
                          {isExpanded ? 'Masquer' : 'Voir'} réservations
                        </button>
                      )}
                      
                      <button 
                        onClick={() => handleDeleteRoom(room.id)}
                        className="btn btn-danger btn-sm"
                        style={{ marginLeft: '0.5rem' }}
                      >
                        Supprimer
                      </button>
                    </div>
                  </div>

                  {/* RÉSERVATIONS DE LA SALLE (affichées si dépliée) */}
                  {isExpanded && roomBookingStats.total > 0 && (
                    <div className="room-bookings" style={{ 
                      marginTop: '1rem', 
                      padding: '1rem',
                      backgroundColor: '#f8f9fa',
                      borderRadius: '4px'
                    }}>
                      <h5>📅 Réservations pour cette salle ({roomBookingStats.total})</h5>
                      
                      {getRoomBookings(room.id).map(booking => (
                        <div key={booking.id} className="booking-item" style={{
                          padding: '0.75rem',
                          marginBottom: '0.5rem',
                          backgroundColor: 'white',
                          borderRadius: '4px',
                          borderLeft: `4px solid ${
                            booking.status === 'confirmed' ? '#28a745' :
                            booking.status === 'pending' ? '#ffc107' :
                            booking.status === 'cancelled' ? '#dc3545' : '#6c757d'
                          }`
                        }}>
                          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                              <strong>Réservation #{booking.id}</strong>
                              <p style={{ margin: '0.25rem 0' }}>
                                Client: {booking.client_first_name} {booking.client_last_name}
                              </p>
                              <p style={{ margin: '0.25rem 0', fontSize: '0.9rem' }}>
                                📅 {new Date(booking.start_datetime).toLocaleString('fr-FR')} 
                                → {new Date(booking.end_datetime).toLocaleString('fr-FR')}
                              </p>
                              <p style={{ margin: '0.25rem 0', fontSize: '0.9rem' }}>
                                💰 Prix: {booking.total_price}DA
                              </p>
                            </div>
                            
                            <div className="booking-actions">
                              <span className={`status-badge ${booking.status}`} style={{
                                padding: '0.25rem 0.5rem',
                                borderRadius: '4px',
                                fontSize: '0.8rem',
                                fontWeight: 'bold',
                                backgroundColor: 
                                  booking.status === 'confirmed' ? '#d4edda' :
                                  booking.status === 'pending' ? '#fff3cd' :
                                  booking.status === 'cancelled' ? '#f8d7da' : '#e2e3e5',
                                color: 
                                  booking.status === 'confirmed' ? '#155724' :
                                  booking.status === 'pending' ? '#856404' :
                                  booking.status === 'cancelled' ? '#721c24' : '#383d41'
                              }}>
                                {booking.status === 'confirmed' ? '✅ Confirmée' :
                                 booking.status === 'pending' ? '⏳ En attente' :
                                 booking.status === 'cancelled' ? '❌ Annulée' : booking.status}
                              </span>
                              
                              {booking.status === 'pending' && (
                                <div style={{ marginTop: '0.5rem', display: 'flex', gap: '0.25rem' }}>
                                  <button 
                                    onClick={() => handleConfirmBooking(booking.id)}
                                    className="btn btn-success btn-sm"
                                    style={{ padding: '0.25rem 0.5rem', fontSize: '0.8rem' }}
                                  >
                                    Confirmer
                                  </button>
                                  <button 
                                    onClick={() => handleCancelBooking(booking.id)}
                                    className="btn btn-danger btn-sm"
                                    style={{ padding: '0.25rem 0.5rem', fontSize: '0.8rem' }}
                                  >
                                    Refuser
                                  </button>
                                </div>
                              )}
                            </div>
                          </div>
                        </div>
                      ))}
                      
                      {getRoomBookings(room.id).length === 0 && (
                        <p style={{ textAlign: 'center', color: '#666', fontStyle: 'italic' }}>
                          Aucune réservation pour cette salle
                        </p>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        ) : (
          <p>Vous n'avez pas encore créé de salles.</p>
        )}
      </div>

      {/* Réservations en attente (vue globale) */}
      <div className="card">
        <h2>📅 Réservations en attente de confirmation</h2>
        
        {loading.bookings ? (
          <p>Chargement des réservations...</p>
        ) : bookings.filter(b => b.status === 'pending').length > 0 ? (
          <div className="bookings-list">
            {bookings
              .filter(b => b.status === 'pending')
              .map(booking => (
                <div key={booking.id} className="booking-item" style={{
                  padding: '1rem',
                  marginBottom: '0.75rem',
                  backgroundColor: '#fff3cd',
                  borderRadius: '4px',
                  border: '1px solid #ffeaa7'
                }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div>
                      <h5 style={{ margin: '0 0 0.5rem 0' }}>Réservation #{booking.id}</h5>
                      <p style={{ margin: '0.25rem 0' }}>
                        <strong>Salle:</strong> {booking.room_title}
                      </p>
                      <p style={{ margin: '0.25rem 0' }}>
                        <strong>Client:</strong> {booking.client_first_name} {booking.client_last_name}
                      </p>
                      <p style={{ margin: '0.25rem 0' }}>
                        <strong>Date:</strong> {new Date(booking.start_datetime).toLocaleString('fr-FR')}
                      </p>
                      <p style={{ margin: '0.25rem 0' }}>
                        <strong>Prix:</strong> {booking.total_price}DA
                      </p>
                    </div>
                    <div className="booking-actions">
                      <button 
                        onClick={() => handleConfirmBooking(booking.id)}
                        className="btn btn-success btn-sm"
                        style={{ marginRight: '0.5rem' }}
                      >
                        ✅ Confirmer
                      </button>
                      <button 
                        onClick={() => handleCancelBooking(booking.id)}
                        className="btn btn-danger btn-sm"
                      >
                        ❌ Refuser
                      </button>
                    </div>
                  </div>
                </div>
              ))}
          </div>
        ) : (
          <p style={{ textAlign: 'center', color: '#666', fontStyle: 'italic' }}>
            Aucune réservation en attente de confirmation
          </p>
        )}
      </div>
    </div>
  );
};

// Ajout des styles CSS
const styles = `
.status-badge.confirmed {
  background-color: #d4edda;
  color: #155724;
}

.status-badge.pending {
  background-color: #fff3cd;
  color: #856404;
}

.status-badge.cancelled {
  background-color: #f8d7da;
  color: #721c24;
}

.pending-badge {
  background-color: #fff3cd;
  color: #856404;
  padding: 0.1rem 0.4rem;
  border-radius: 3px;
  font-size: 0.8rem;
  margin-right: 0.5rem;
}

.confirmed-badge {
  background-color: #d4edda;
  color: #155724;
  padding: 0.1rem 0.4rem;
  border-radius: 3px;
  font-size: 0.8rem;
  margin-right: 0.5rem;
}

.btn-sm {
  padding: 0.25rem 0.5rem;
  font-size: 0.875rem;
}

.btn-success {
  background-color: #28a745;
  color: white;
}

.btn-success:hover {
  background-color: #218838;
}

.btn-danger {
  background-color: #dc3545;
  color: white;
}

.btn-danger:hover {
  background-color: #c82333;
}
`;

// Ajouter les styles
const styleSheet = document.createElement("style");
styleSheet.textContent = styles;
document.head.appendChild(styleSheet);

export default OwnerDashboard;
